import { z } from "zod";

/**
 * Statement structure generated by LLM
 */
export const GeneratedStatementSchema = z.object({
  text: z.string().min(10, "Statement text must be at least 10 characters"),
  isTrue: z.boolean(),
  groundingRationale: z.string().min(10, "Rationale must explain source grounding"),
});

/**
 * Complete LLM Structured Output for a Devil's Advocate Quiz Question
 */
export const GeneratedQuizQuestionSchema = z
  .object({
    concept: z.string().min(3, "Concept description required"),
    difficulty: z.enum(["foundational", "intermediate", "advanced"]),
    groundingChunkIds: z.array(z.string()).min(1, "At least one grounding chunk ID required"),
    statements: z
      .array(GeneratedStatementSchema)
      .length(3, "Must generate exactly 3 statements (2 lies + 1 truth)"),
  })
  .refine(
    (data) => {
      const trueCount = data.statements.filter((s) => s.isTrue).length;
      return trueCount === 1;
    },
    {
      message: "Generated question must contain exactly 1 true statement and 2 false statements",
      path: ["statements"],
    }
  );

export type GeneratedStatement = z.infer<typeof GeneratedStatementSchema>;
export type GeneratedQuizQuestion = z.infer<typeof GeneratedQuizQuestionSchema>;
